  "sec-suid-credentials": {"prompt": "Binario setuid propiedad de user backup. ¿Ejecutarlo implica necesariamente EUID 0? sí/no", "answer": "no", "hint": "El owner concreto determina la transición."},
  "sec-capabilities-nnp": {"prompt": "¿no_new_privs revoca automáticamente los file descriptors privilegiados ya abiertos? sí/no", "answer": "no", "hint": "Su garantía principal limita ganancias por exec."},
  "sec-sandbox-seccomp": {"prompt": "¿Un filtro seccomp que permite openat demuestra que cualquier openat del proceso es seguro? sí/no", "answer": "no", "hint": "Reachability y lógica/autorización son cosas distintas."},
  "sec-containers-isolation": {"prompt": "¿Un container no-root con socket de control del runtime host writable puede seguir representar alta autoridad? sí/no", "answer": "si", "hint": "El socket puede dominar el modelo de privilegios."},
  "sec-isolation-boundaries": {"prompt": "¿Dos containers separados pero con el mismo directorio host writable están aislados respecto a modificar esos datos? sí/no", "answer": "no", "hint": "Existe un recurso compartido de escritura."},
